import { getIconList } from "@/api/system/ciModel";
export default {
  props: ['isShow', 'selectIcon'],
  data: function data() {
    return {
      iconList: [],
      activeIcon: ''
    };
  },
  mounted: function mounted() {
    this.initData();
  },
  methods: {
    initData: function initData() {
      var _this = this;
      this.activeIcon = this.selectIcon;
      getIconList({
        type: ['cmdb']
      }).then(function (res) {
        // console.log(res)
        _this.iconList = res.Return;
      });
    },
    changeIcon: function changeIcon(item) {
      this.activeIcon = item;
    },
    save: function save() {
      this.$emit('submitIcon', this.activeIcon);
    }
  }
};
